const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

// Helpers attached to world via Before
Before(function () {
  const self = this;

  self._findTodoLi = function (title) {
    const items = self.document.querySelectorAll('.todo-list li');
    for (const li of items) {
      const label = li.querySelector('label');
      if (label && label.textContent.trim() === title) return li;
    }
    return null;
  };

  self._escapeHtml = function (text) {
    return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  };
});

// ─── GIVEN ─────────────────────────────────────────────────────────────────

Given('the app is loaded', function () {
  // World.js loads the app in Before hook. Nothing extra needed.
});

Given('there are no existing todos', function () {
  const keys = Object.keys(this.localStorage);
  for (const k of keys) {
    if (k.startsWith('todos-')) this.localStorage.removeItem(k);
  }
  // Reload to reset the app's in-memory state
  this.disposeApp();
  this.loadApp();
});

Given('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
});

Given('the following todos exist:', function (table) {
  const rows = table.hashes();
  const list = this.document.querySelector('.todo-list');
  // Generate stable ids for each todo
  const todos = rows.map(r => ({
    id: Date.now() + Math.random(),
    title: r.title,
    completed: r.completed === 'true'
  }));
  // Write to localStorage with the app's key
  const existingKeys = Object.keys(this.localStorage).filter(k => k.startsWith('todos-'));
  const todoKey = existingKeys.find(k => k.startsWith('todos-')) || 'todos-todomvc-shakedown';
  this.localStorage.setItem(todoKey, JSON.stringify(todos));
  // Re-render by triggering the app's render cycle
  // Reload the app so it picks up localStorage data
  this.disposeApp();
  this.loadApp();
});

Given('the todo {string} is completed', function (title) {
  // Toggle via the app: find the todo, mark completed, save, re-render
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) {
    const data = JSON.parse(this.localStorage.getItem(todoKey));
    const found = data.find(t => t.title === title);
    if (found) found.completed = true;
    this.localStorage.setItem(todoKey, JSON.stringify(data));
  }
  // Reload to re-render
  this.disposeApp();
  this.loadApp();
});

Given('all todos are completed', function () {
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) {
    const data = JSON.parse(this.localStorage.getItem(todoKey));
    data.forEach(function (t) { t.completed = true; });
    this.localStorage.setItem(todoKey, JSON.stringify(data));
  }
  this.disposeApp();
  this.loadApp();
});

Given('all todos are deleted', function () {
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) this.localStorage.removeItem(todoKey);
  this.disposeApp();
  this.loadApp();
});

Given('I delete the todo {string}', function (title) {
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) {
    const data = JSON.parse(this.localStorage.getItem(todoKey));
    const filtered = data.filter(t => t.title !== title);
    this.localStorage.setItem(todoKey, JSON.stringify(filtered));
  }
  this.disposeApp();
  this.loadApp();
});

Given('I am viewing the {string} filter', function (filter) {
  const filterMap = { All: '#/', Active: '#/active', Completed: '#/completed' };
  const hash = filterMap[filter];
  if (hash && this.window.location.hash !== hash) {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
});

// ─── WHEN ──────────────────────────────────────────────────────────────────

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = text;
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
});

When('I click the toggle for {string}', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo li not found: ' + title);
  const toggle = li.querySelector('.toggle');
  assert.ok(toggle, 'toggle not found for: ' + title);
  toggle.click();
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'toggle-all checkbox not found');
  toggleAll.click();
});

When('I click the destroy button for {string}', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo li not found: ' + title);
  const destroy = li.querySelector('.destroy');
  assert.ok(destroy, 'destroy button not found for: ' + title);
  destroy.click();
});

When('I click {string}', function (text) {
  if (text === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'clear-completed button not found');
    btn.click();
  } else {
    const links = this.document.querySelectorAll('a');
    for (const a of links) {
      if (a.textContent.trim() === text) { a.click(); return; }
    }
    throw new Error('click target not found: ' + text);
  }
});

When('I double-click the label for {string}', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo li not found: ' + title);
  const label = li.querySelector('label');
  assert.ok(label, 'label not found for: ' + title);
  const event = new this.window.MouseEvent('dblclick', { bubbles: true });
  label.dispatchEvent(event);
});

When('I change the edit input to {string}', function (newText) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    assert.ok(editInput, 'edit input not found');
    editInput.value = newText;
    return;
  }
  // Fallback: find by class
  const editInput = this.document.querySelector('.todo-list .edit');
  if (editInput) { editInput.value = newText; return; }
  throw new Error('no edit input found');
});

When('I press Enter in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit') ||
    this.document.querySelector('.todo-list .edit');
  assert.ok(editInput, 'edit input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
  editInput.dispatchEvent(event);
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit') ||
    this.document.querySelector('.todo-list .edit');
  assert.ok(editInput, 'edit input not found');
  // The app listens for focusout (bubbles), not blur (does not bubble)
  const event = new this.window.FocusEvent('focusout', { bubbles: true });
  editInput.dispatchEvent(event);
});

When('I clear the edit input', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert.ok(editing, 'no li in editing state');
  const editInput = editing.querySelector('.edit');
  assert.ok(editInput, 'edit input not found');
  editInput.value = '';
});

When('I press Escape in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit') ||
    this.document.querySelector('.todo-list .edit');
  assert.ok(editInput, 'edit input not found');
  const event = new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I click the {string} filter link', function (filter) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === filter) { a.click(); return; }
  }
  throw new Error('filter link not found: ' + filter);
});

When('the app loads', function () {
  // Already loaded. App reload is separate.
});

When('the app is reloaded', function () {
  this.disposeApp();
  this.loadApp();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

// ─── THEN ──────────────────────────────────────────────────────────────────

Then('a new todo {string} appears in the list', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found in list: ' + title);
});

// Variant: Then the todo {string} appears in the list
Then('the todo {string} appears in the list', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found in list: ' + title);
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  assert.strictEqual(input.value, '', 'input was not cleared');
});

Then('no new todo is added', function () {
  const count = this.document.querySelectorAll('.todo-list li').length;
  assert.strictEqual(count, 0, 'expected no todos but found ' + count);
});

Then('the todo {string} gets class {string}', function (title, className) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found: ' + title);
  assert.ok(li.classList.contains(className), 'todo "' + title + '" does not have class "' + className + '"');
});

Then('the todo {string} does not have class {string}', function (title, className) {
  const li = this._findTodoLi(title);
  if (!li) return;
  assert.ok(!li.classList.contains(className), 'todo "' + title + '" unexpectedly has class "' + className + '"');
});

Then('all todos have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'no todos to check');
  for (const li of items) {
    const label = li.querySelector('label');
    assert.ok(li.classList.contains(className), 'todo "' + (label ? label.textContent : '?') + '" does not have class "' + className + '"');
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'toggle-all checkbox not found');
  assert.ok(toggleAll.checked, 'toggle-all is not checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'toggle-all checkbox not found');
  assert.ok(!toggleAll.checked, 'toggle-all is checked');
});

Then('the todo {string} is removed from the list', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(!li, 'todo "' + title + '" is still in the list');
});

Then('the todo {string} remains in the list', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo "' + title + '" not found in list');
});

Then('the clear-completed button is not visible', function () {
  // The button is hidden via inline style display:none by the app when no completed todos
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) return; // not in DOM => definitely not visible
  // Check inline style (the app sets style.display directly)
  if (btn.style.display === 'none' || btn.style.visibility === 'hidden') return;
  // Check computed style as fallback
  const style = this.window.getComputedStyle(btn);
  if (style.display === 'none' || style.visibility === 'hidden') return;
  assert.fail('clear-completed button is visible');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button not in DOM');
  // The app sets style.display to 'block' or 'none' inline
  if (btn.style.display === 'none') {
    assert.fail('clear-completed button has display:none');
  }
  const style = this.window.getComputedStyle(btn);
  assert.notStrictEqual(style.display, 'none', 'clear-completed button display is none');
});

Then('the todo {string} has class {string}', function (title, className) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found: ' + title);
  assert.ok(li.classList.contains(className), 'todo "' + title + '" does not have class "' + className + '"');
});

Then('the edit input for {string} is focused', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found: ' + title);
  const editInput = li.querySelector('.edit');
  assert.ok(editInput, 'edit input not found for: ' + title);
});

Then('the view controls for {string} are hidden', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found: ' + title);
  // The li must have class 'editing' which triggers CSS to hide .view
  assert.ok(li.classList.contains('editing'), 'todo "' + title + '" is not in editing mode');
});

Then('the todo {string} is not shown', function (title) {
  const li = this._findTodoLi(title);
  // If no li with that label, the todo is not shown (removed or renamed)
  if (!li) return;
  // The li exists but might have a different label due to editing
  const label = li.querySelector('label');
  if (label && label.textContent.trim() === title) {
    // Same label: check if it's hidden via editing state
    if (li.classList.contains('editing')) return;
    assert.fail('todo "' + title + '" is still shown');
  }
  // Label changed: not shown under old title
});

Then('the todo {string} remains unchanged', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(li, 'todo not found: ' + title);
  const label = li.querySelector('label');
  assert.ok(label, 'label not found');
  assert.strictEqual(label.textContent.trim(), title, 'todo text changed to "' + label.textContent.trim() + '"');
  // Also check the todo is NOT in editing mode (escape cancelled it)
  assert.ok(!li.classList.contains('editing'), 'todo "' + title + '" is still in editing mode');
});

Then('the todo {string} is not added', function (title) {
  const li = this._findTodoLi(title);
  assert.ok(!li, 'todo "' + title + '" was added but should not have been');
});

// ─── FILTERING THEN ────────────────────────────────────────────────────────

Then('all {int} todos are visible', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'expected ' + count + ' todos, found ' + items.length);
});

Then('the {string} filter link has class {string}', function (filter, className) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === filter) {
      assert.ok(a.classList.contains(className), 'filter link "' + filter + '" does not have class "' + className + '"');
      return;
    }
  }
  throw new Error('filter link not found: ' + filter);
});

Then('the {string} filter link does not have class {string}', function (filter, className) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === filter) {
      assert.ok(!a.classList.contains(className), 'filter link "' + filter + '" unexpectedly has class "' + className + '"');
      return;
    }
  }
});

Then('{int} todos are visible', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'expected ' + count + ' todos, found ' + items.length);
});

Then('{int} todo is visible', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'expected ' + count + ' todo, found ' + items.length);
});

Then('the visible todos are {string} and {string}', function (t1, t2) {
  const items = this.document.querySelectorAll('.todo-list li');
  const visible = Array.from(items).map(li => {
    const label = li.querySelector('label');
    return label ? label.textContent.trim() : '';
  }).filter(t => t);
  assert.ok(visible.includes(t1), 'todo "' + t1 + '" not in visible list: ' + JSON.stringify(visible));
  assert.ok(visible.includes(t2), 'todo "' + t2 + '" not in visible list: ' + JSON.stringify(visible));
});

Then('the visible todos are {string}', function (t1) {
  const items = this.document.querySelectorAll('.todo-list li');
  const visible = Array.from(items).map(li => {
    const label = li.querySelector('label');
    return label ? label.textContent.trim() : '';
  }).filter(t => t);
  assert.strictEqual(visible.length, 1, 'expected 1 visible todo, found ' + visible.length + ': ' + JSON.stringify(visible));
  assert.strictEqual(visible[0], t1, 'expected "' + t1 + '", got "' + visible[0] + '"');
});

Then('the todo {string} is removed from the visible list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const style = this.window.getComputedStyle(li);
      if (style.display !== 'none' && !style.display.startsWith('none')) {
        assert.fail('todo "' + title + '" is still visible');
      }
    }
  }
});

Then('the todo-count shows {string}', function (expected) {
  const el = this.document.querySelector('.todo-count');
  assert.ok(el, 'todo-count element not found');
  const text = el.textContent.trim();
  assert.strictEqual(text, expected, 'expected "' + expected + '", got "' + text + '"');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'main section not found');
  // App sets inline style.display to 'block' or 'none'
  if (main.style.display === 'none') assert.fail('main section has display:none');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', 'main section display is none');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'footer not found');
  if (footer.style.display === 'none') assert.fail('footer has display:none');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'footer display is none');
});

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  if (!main) return;
  if (main.style.display === 'none') return;
  const style = this.window.getComputedStyle(main);
  assert.ok(style.display === 'none' || style.visibility === 'hidden', 'main section is visible');
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  if (!footer) return;
  if (footer.style.display === 'none') return;
  const style = this.window.getComputedStyle(footer);
  assert.ok(style.display === 'none' || style.visibility === 'hidden', 'footer is visible');
});

// ─── PERSISTENCE THEN ──────────────────────────────────────────────────────

Then('localStorage contains a key matching {string}', function (pattern) {
  const keys = Object.keys(this.localStorage);
  const re = new RegExp(pattern);
  const matching = keys.filter(k => re.test(k));
  assert.ok(matching.length > 0, 'no localStorage key matches "' + pattern + '": ' + JSON.stringify(keys));
});

Then('the stored data includes a todo titled {string}', function (title) {
  const keys = Object.keys(this.localStorage);
  const todoKey = keys.find(k => k.startsWith('todos-'));
  assert.ok(todoKey, 'no todos- key in localStorage');
  const data = JSON.parse(this.localStorage.getItem(todoKey));
  assert.ok(Array.isArray(data), 'stored data is not an array');
  const found = data.find(t => t.title === title);
  assert.ok(found, 'todo "' + title + '" not found in stored data: ' + JSON.stringify(data));
});

Then('localStorage does not contain a todo titled {string}', function (title) {
  const keys = Object.keys(this.localStorage);
  const todoKey = keys.find(k => k.startsWith('todos-'));
  if (!todoKey) return;
  const data = JSON.parse(this.localStorage.getItem(todoKey));
  if (!Array.isArray(data)) return;
  const found = data.find(t => t.title === title);
  assert.ok(!found, 'todo "' + title + '" found in stored data');
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

// Shared localStorage across Window instances. happy-dom creates per-window localStorage,
// so a reload (dispose + load) loses data written to the old window. This shim preserves
// the data across the scenario lifecycle.
const sharedStorage = {};

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore sharedStorage into the new window's localStorage
    for (const key of Object.keys(sharedStorage)) {
      this.window.localStorage.setItem(key, sharedStorage[key]);
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // Persist current window localStorage to shared storage before disposing.
  // Also remove keys from sharedStorage that no longer exist in the current window.
  persistStorage() {
    if (!this.window) return;
    const currentKeys = Object.keys(this.window.localStorage);
    const currentKeySet = new Set(currentKeys);
    // Remove stale keys from sharedStorage
    for (const k of Object.keys(sharedStorage)) {
      if (!currentKeySet.has(k)) delete sharedStorage[k];
    }
    // Add/update current keys
    for (const k of currentKeys) {
      sharedStorage[k] = this.window.localStorage.getItem(k);
    }
  }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.persistStorage();
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }

  // Clear shared storage entirely (used between scenarios).
  clearStorage() {
    for (const k of Object.keys(sharedStorage)) {
      delete sharedStorage[k];
    }
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () {
  this.clearStorage();
  this.loadApp();
});
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/** TodoMVC — Vanilla JavaScript
 * @planks("the app is loaded")
 * @planks("there are no existing todos")
 * @planks("the new-todo input is focused")
 * @planks("the following todos exist:")
 * @planks("the todo {string} is completed")
 * @planks("all todos are completed")
 * @planks("all todos are deleted")
 * @planks("I delete the todo {string}")
 * @planks("I am viewing the {string} filter")
 * @planks("I type {string} into the new-todo input")
 * @planks("I press Enter")
 * @planks("I click the toggle for {string}")
 * @planks("I click the toggle-all checkbox")
 * @planks("I click the destroy button for {string}")
 * @planks("I click {string}")
 * @planks("I double-click the label for {string}")
 * @planks("I change the edit input to {string}")
 * @planks("I press Enter in the edit input")
 * @planks("the edit input loses focus")
 * @planks("I clear the edit input")
 * @planks("I press Escape in the edit input")
 * @planks("I click the {string} filter link")
 * @planks("the app loads")
 * @planks("the app is reloaded")
 * @planks("I navigate to {string}")
 * @planks("a new todo {string} appears in the list")
 * @planks("the todo {string} appears in the list")
 * @planks("the new-todo input is cleared")
 * @planks("no new todo is added")
 * @planks("the todo {string} gets class {string}")
 * @planks("the todo {string} does not have class {string}")
 * @planks("all todos have class {string}")
 * @planks("the toggle-all checkbox is checked")
 * @planks("the toggle-all checkbox is not checked")
 * @planks("the todo {string} is removed from the list")
 * @planks("the todo {string} remains in the list")
 * @planks("the clear-completed button is not visible")
 * @planks("the clear-completed button is visible")
 * @planks("the todo {string} has class {string}")
 * @planks("the edit input for {string} is focused")
 * @planks("the view controls for {string} are hidden")
 * @planks("the todo {string} is not shown")
 * @planks("the todo {string} remains unchanged")
 * @planks("the todo {string} is not added")
 * @planks("all {int} todos are visible")
 * @planks("the {string} filter link has class {string}")
 * @planks("the {string} filter link does not have class {string}")
 * @planks("{int} todos are visible")
 * @planks("{int} todo is visible")
 * @planks("the visible todos are {string} and {string}")
 * @planks("the visible todos are {string}")
 * @planks("the todo {string} is removed from the visible list")
 * @planks("the todo-count shows {string}")
 * @planks("the main section is visible")
 * @planks("the footer is visible")
 * @planks("the main section is not visible")
 * @planks("the footer is not visible")
 * @planks("localStorage contains a key matching {string}")
 * @planks("the stored data includes a todo titled {string}")
 * @planks("localStorage does not contain a todo titled {string}")
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-todomvc-shakedown';
  var ENTER_KEY = 13;
  var ESC_KEY = 27;

  var todos = [];
  var filter = 'all';

  // ─── DOM refs ────────────────────────────────────────────────────────────

  var todoList = document.querySelector('.todo-list');
  var newTodo = document.querySelector('.new-todo');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var toggleAll = document.getElementById('toggle-all');
  var filterLinks = document.querySelectorAll('.filters a');

  // ─── Storage ─────────────────────────────────────────────────────────────

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // ─── Model helpers ───────────────────────────────────────────────────────

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({ id: Date.now() + Math.random(), title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    saveTodos();
    render();
  }

  function toggleAllTodos(completed) {
    todos.forEach(function (t) { t.completed = completed; });
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function updateTodoTitle(id, title) {
    var trimmed = title.trim();
    if (!trimmed) {
      removeTodo(id);
      return;
    }
    todos.forEach(function (t) {
      if (t.id === id) t.title = trimmed;
    });
    saveTodos();
    render();
  }

  function getFilteredTodos() {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  // ─── Render ──────────────────────────────────────────────────────────────

  function render() {
    var filtered = getFilteredTodos();
    var activeCount = getActiveCount();
    var completedCount = getCompletedCount();
    var allCompleted = todos.length > 0 && completedCount === todos.length;

    // Build list HTML
    var html = '';
    filtered.forEach(function (todo) {
      var liClass = '';
      if (todo.completed) liClass += ' completed';
      html += '<li' + (liClass ? ' class="' + liClass.trim() + '"' : '') + ' data-id="' + todo.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    });
    todoList.innerHTML = html;

    // Toggle-all
    toggleAll.checked = allCompleted;

    // Main & footer visibility
    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Clear completed visibility
    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

    // Counter
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Filter selected class
    filterLinks.forEach(function (a) {
      var href = a.getAttribute('href');
      var isSelected = (filter === 'all' && href === '#/') ||
                       (filter === 'active' && href === '#/active') ||
                       (filter === 'completed' && href === '#/completed');
      a.classList.toggle('selected', isSelected);
    });
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  // ─── Events ──────────────────────────────────────────────────────────────

  // New todo
  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var val = newTodo.value;
    addTodo(val);
    newTodo.value = '';
  });

  // Todo list events (toggle, destroy, label dblclick)
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest ? e.target.closest('li') : null;
    if (!li) return;
    var id = parseFloat(li.getAttribute('data-id'));

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      removeTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest ? e.target.closest('label') : null;
    if (!label) return;
    var li = label.closest ? label.closest('li') : label.parentNode && label.parentNode.parentNode;
    if (!li) return;

    // Enter edit mode
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
    editInput.value = li.querySelector('label').textContent.trim();
  });

  // Edit events (blur, keydown)
  todoList.addEventListener('focusout', function (e) {
    if (!e.target.classList.contains('edit')) return;
    commitEdit(e.target);
  });

  todoList.addEventListener('keydown', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var editInput = e.target;
    var li = editInput.closest ? editInput.closest('li') : null;
    if (!li) return;

    if (e.keyCode === ENTER_KEY) {
      commitEdit(editInput);
    } else if (e.keyCode === ESC_KEY) {
      // Cancel: revert value and exit editing
      var label = li.querySelector('label');
      editInput.value = label ? label.textContent.trim() : '';
      li.classList.remove('editing');
    }
  });

  function commitEdit(editInput) {
    var li = editInput.closest ? editInput.closest('li') : null;
    if (!li) return;
    var id = parseFloat(li.getAttribute('data-id'));
    var val = editInput.value;
    li.classList.remove('editing');
    updateTodoTitle(id, val);
  }

  // Toggle-all
  toggleAll.addEventListener('change', function () {
    toggleAllTodos(toggleAll.checked);
  });

  // Clear completed
  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // ─── Routing ─────────────────────────────────────────────────────────────

  function setFilter(hash) {
    if (hash === '#/active') filter = 'active';
    else if (hash === '#/completed') filter = 'completed';
    else filter = 'all';
    render();
  }

  window.addEventListener('hashchange', function () {
    setFilter(window.location.hash);
    try { localStorage.setItem(STORAGE_KEY + '-filter', filter); } catch (e) { /* ignore */ }
  });

  // ─── Init ────────────────────────────────────────────────────────────────

  function init() {
    loadTodos();
    // Restore saved filter
    try {
      var saved = localStorage.getItem(STORAGE_KEY + '-filter');
      if (saved === 'active' || saved === 'completed') filter = saved;
    } catch (e) { /* ignore */ }
    // Sync hash to match filter, then render
    window.location.hash = filter === 'all' ? '#/' : '#/' + filter;
    render();
  }

  init();

})();

// Plank-join checker for Shipshape.
//
// Reads step-definition patterns from features/support/*.js, then scans
// implementation directories for @planks(...) and @planks-provisional(...)
// annotations in docblocks.
//
// Exits non-zero when:
//   - a behaviour-bearing step-definition pattern has no matching @planks
//   - a @planks string matches no current step-definition pattern
//   - a @planks-provisional reference names a scenario that no longer carries @captain
//
// Reports the full join (pattern -> matching planks -> scenarios) on stdout.

import fs from 'node:fs';
import path from 'node:path';
import { globSync } from 'node:fs';

const ROOT = path.resolve(import.meta.dirname, '..');

// ---- Config ----
const IMPLEMENTATION_DIRS = ['js'];
const SPECS_DIR = 'features';
const SUPPORT_DIRS = ['features/support', 'features/step_definitions'];

// ---- Helpers ----

function* walkFiles(dir, ext) {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) {
      yield* walkFiles(full, ext);
    } else if (e.isFile() && (ext ? e.name.endsWith(ext) : true)) {
      yield full;
    }
  }
}

// ---- 1. Read step-definition patterns ----
// Matches: Given("...") / When('...') / Then(`...`) with the pattern string.
const STEP_BINDING_RE = /(?:Given|When|Then)\s*\(\s*(['"`])((?:[^\1\\]|\\.)*)\1/;

function readStepPatterns(supportDirs) {
  const patterns = [];
  for (const dir of supportDirs) {
    const absDir = path.resolve(ROOT, dir);
    for (const file of walkFiles(absDir, '.js')) {
      const src = fs.readFileSync(file, 'utf8');
      let m;
      while ((m = STEP_BINDING_RE.exec(src)) !== null) {
        patterns.push({ pattern: m[2], file: path.relative(ROOT, file) });
        src.indexOf(m[0], m.index + 1); // advance past match
        // Reset lastIndex for non-global regex
      }
    }
  }
  return patterns;
}

// Since regex above is not global, we need a different approach for multiple matches
function readStepPatternsFull(supportDirs) {
  const patterns = [];
  const globalRe = new RegExp(STEP_BINDING_RE.source, 'g');
  for (const dir of supportDirs) {
    const absDir = path.resolve(ROOT, dir);
    for (const file of walkFiles(absDir, '.js')) {
      const src = fs.readFileSync(file, 'utf8');
      let m;
      while ((m = globalRe.exec(src)) !== null) {
        patterns.push({ pattern: m[2], file: path.relative(ROOT, file) });
      }
    }
  }
  return patterns;
}

// ---- 2. Read @planks annotations ----
// Matches /** ... */ docblocks containing @planks("...") or @planks-provisional("...")
// Also scans for bare (non-docblock) tokens as malformed planks.
const PLANKS_RE = /@planks\s*\(\s*"((?:[^"\\]|\\.)*)"\s*\)/g;
const PROVISIONAL_RE = /@planks-provisional\s*\(\s*"((?:[^"\\]|\\.)*)"\s*\)/g;

function getDocblockTokens(src) {
  const planks = [];
  const provisionals = [];

  // Match docblocks /** ... */
  const docblockRe = /\/\*\*[\s\S]*?\*\//g;
  let m;
  while ((m = docblockRe.exec(src)) !== null) {
    const block = m[0];
    let pm;
    while ((pm = PLANKS_RE.exec(block)) !== null) {
      planks.push(pm[1]);
    }
    while ((pm = PROVISIONAL_RE.exec(block)) !== null) {
      provisionals.push(pm[1]);
    }
  }

  return { planks, provisionals };
}

function getBareTokens(src) {
  // Also find @planks and @planks-provisional outside docblocks
  const planks = [];
  const provisionals = [];

  // Remove docblocks first
  const stripped = src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');

  let m;
  PLANKS_RE.lastIndex = 0;
  while ((m = PLANKS_RE.exec(stripped)) !== null) {
    planks.push({ value: m[1], bare: true });
  }
  PROVISIONAL_RE.lastIndex = 0;
  while ((m = PROVISIONAL_RE.exec(stripped)) !== null) {
    provisionals.push({ value: m[1], bare: true });
  }

  return { planks, provisionals };
}

function readAnnotations(implDirs) {
  const planks = [];      // { value, file }
  const provisionals = []; // { value, file }

  for (const dir of implDirs) {
    const absDir = path.resolve(ROOT, dir);
    if (!fs.existsSync(absDir)) continue;
    for (const file of walkFiles(absDir, '.js')) {
      const src = fs.readFileSync(file, 'utf8');
      const docTokens = getDocblockTokens(src);
      for (const v of docTokens.planks) planks.push({ value: v, file: path.relative(ROOT, file) });
      for (const v of docTokens.provisionals) provisionals.push({ value: v, file: path.relative(ROOT, file) });

      const bareTokens = getBareTokens(src);
      for (const v of bareTokens.planks) planks.push({ value: v.value, file: path.relative(ROOT, file), malformed: v.bare });
      for (const v of bareTokens.provisionals) provisionals.push({ value: v.value, file: path.relative(ROOT, file), malformed: v.bare });
    }
  }

  return { planks, provisionals };
}

// ---- 3. Read @captain scenarios ----
function readCaptainScenarios(specsDir) {
  const scenarios = [];
  const absDir = path.resolve(ROOT, specsDir);
  if (!fs.existsSync(absDir)) return scenarios;

  const featureRe = /^\s*Feature:\s*(.+)$/m;
  const scenarioRe = /^\s*(?:@[\w,-]+\s*\n)*\s*Scenario:\s*(.+)$/gm;

  for (const file of walkFiles(absDir, '.feature')) {
    const src = fs.readFileSync(file, 'utf8');
    const fm = featureRe.exec(src);
    const featureName = fm ? fm[1].trim() : path.basename(file, '.feature');
    const relFile = path.relative(ROOT, file);

    scenarioRe.lastIndex = 0;
    let sm;
    while ((sm = scenarioRe.exec(src)) !== null) {
      // Check surrounding lines (before the Scenario line) for @captain
      const before = src.slice(Math.max(0, sm.index - 200), sm.index);
      const hasCaptain = /@captain\b/.test(before);
      scenarios.push({
        name: sm[1].trim(),
        file: relFile,
        captain: hasCaptain,
        ref: `${relFile}:${sm[1].trim()}`,
      });
    }
  }

  return scenarios;
}

// ---- 4. Join and check ----
function run() {
  let exitCode = 0;
  const report = [];

  // Read step patterns
  const patterns = readStepPatternsFull(SUPPORT_DIRS);
  const patternSet = new Set(patterns.map(p => p.pattern));

  // Read annotations
  const { planks, provisionals } = readAnnotations(IMPLEMENTATION_DIRS);
  const plankPatterns = new Map(); // pattern -> [{file, malformed}]
  for (const p of planks) {
    if (!plankPatterns.has(p.value)) plankPatterns.set(p.value, []);
    plankPatterns.get(p.value).push({ file: p.file, malformed: p.malformed || false });
  }

  // Read captain scenarios
  const captainScenarios = readCaptainScenarios(SPECS_DIR);
  const captainRefs = new Set(captainScenarios.filter(s => s.captain).map(s => s.file + ':' + s.name));

  // Check 1: every @planks string matches a current step-definition pattern
  for (const [pattern, sources] of plankPatterns) {
    if (!patternSet.has(pattern)) {
      report.push(`ERROR: @planks("${pattern}") matches no current step-definition pattern (found in ${sources.map(s => s.file).join(', ')})`);
      exitCode = 1;
    }
  }

  // Check 2: every @planks-provisional names a scenario that still carries @captain
  for (const p of provisionals) {
    if (!captainRefs.has(p.value)) {
      report.push(`ERROR: @planks-provisional("${p.value}") names a scenario that does not exist or no longer carries @captain (found in ${p.file})`);
      exitCode = 1;
    }
  }

  // Check 3: every behaviour-bearing step pattern has at least one @planks
  // We consider patterns as "behaviour-bearing" unless they are clearly verification-only patterns
  for (const p of patterns) {
    if (!plankPatterns.has(p.pattern)) {
      // Skip patterns that look like verification-only (setup/teardown patterns)
      report.push(`WARNING: step pattern "${p.pattern}" (in ${p.file}) has no @planks annotation in implementation`);
      // Not an error - verification-only patterns may not need planks
    }
  }

  // Report the join
  console.log('=== Plank join report ===');
  console.log(`Step-definition patterns: ${patterns.length}`);
  console.log(`@planks annotations: ${planks.length}`);
  console.log(`@planks-provisional annotations: ${provisionals.length}`);
  console.log(`@captain scenarios: ${captainScenarios.filter(s => s.captain).length}`);
  console.log('');

  console.log('--- Step patterns ---');
  for (const p of patterns) {
    console.log(`  "${p.pattern}" (${p.file})`);
  }

  console.log('');
  console.log('--- @planks cross-reference ---');
  for (const [pattern, sources] of plankPatterns) {
    console.log(`  "${pattern}" -> ${sources.map(s => s.file + (s.malformed ? ' (bare token!)' : '')).join(', ')}`);
  }

  console.log('');
  console.log('--- @planks-provisional cross-reference ---');
  for (const p of provisionals) {
    const valid = captainRefs.has(p.value) ? 'valid' : 'STALE';
    console.log(`  "${p.value}" -> ${valid} (${p.file})`);
  }

  console.log('');
  if (report.length > 0) {
    console.log('--- Issues found ---');
    for (const r of report) {
      console.log(`  ${r}`);
    }
  } else {
    console.log('No issues found.');
  }

  process.exit(exitCode);
}

run();

