Given('there are no existing todos', function () {
  const keys = Object.keys(this.localStorage);
  for (const k of keys) {
    if (k.startsWith('todos-')) this.localStorage.removeItem(k);
  }
  // Reload to reset the app's in-memory state
  this.disposeApp();
  this.loadApp();
});

Given('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
});

Given('the following todos exist:', function (table) {
  const rows = table.hashes();
  const list = this.document.querySelector('.todo-list');
  // Generate stable ids for each todo
  const todos = rows.map(r => ({
    id: Date.now() + Math.random(),
    title: r.title,
    completed: r.completed === 'true'
  }));
  // Write to localStorage with the app's key
  const existingKeys = Object.keys(this.localStorage).filter(k => k.startsWith('todos-'));
  const todoKey = existingKeys.find(k => k.startsWith('todos-')) || 'todos-todomvc-shakedown';
  this.localStorage.setItem(todoKey, JSON.stringify(todos));
  // Re-render by triggering the app's render cycle
  // Reload the app so it picks up localStorage data
  this.disposeApp();
  this.loadApp();
});

Given('the todo {string} is completed', function (title) {
  // Toggle via the app: find the todo, mark completed, save, re-render
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) {
    const data = JSON.parse(this.localStorage.getItem(todoKey));
    const found = data.find(t => t.title === title);
    if (found) found.completed = true;
    this.localStorage.setItem(todoKey, JSON.stringify(data));
  }
  // Reload to re-render
  this.disposeApp();
  this.loadApp();
});

Given('all todos are completed', function () {
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) {
    const data = JSON.parse(this.localStorage.getItem(todoKey));
    data.forEach(function (t) { t.completed = true; });
    this.localStorage.setItem(todoKey, JSON.stringify(data));
  }
  this.disposeApp();
  this.loadApp();
});

Given('all todos are deleted', function () {
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) this.localStorage.removeItem(todoKey);
  this.disposeApp();
  this.loadApp();
});

Given('I delete the todo {string}', function (title) {
  const todoKey = Object.keys(this.localStorage).find(k => k.startsWith('todos-'));
  if (todoKey) {
    const data = JSON.parse(this.localStorage.getItem(todoKey));
    const filtered = data.filter(t => t.title !== title);
    this.localStorage.setItem(todoKey, JSON.stringify(filtered));
  }
  this.disposeApp();
  this.loadApp();
});

